with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , CRITICAL_ILLNESS as HEAD_BASIS_DESCRIPTION
        , EMI_JOBLOSS_DATE as HEAD_ONSET_DATE
        , EMI_OTHERORG_DATE as HEAD_RESOLUTION_DATE
        , TTD_LEAVE_FROM as HEAD_CLAIMED_PERIOD_FROM_DATE
        , TTD_LEAVE_TO as HEAD_CLAIMED_PERIOD_TO_DATE
        , EMI_NO_DAYS as HEAD_ASSESSED_DURATION_DAYS
        , TTD_DUR_LEAVES as HEAD_CLAIMED_DURATION_DAYS
        , NO_EMI_PAID as HEAD_BASIS_COUNT
        , FUNERAL_DATE as HEAD_EVENT_DATE
        , FAMILY_FROM_CITY as TRAVEL_FROM_CITY
        , FAMILY_TO_CITY as TRAVEL_TO_CITY
        , cast(null as varchar) as HEAD_BASE_SUM_INSURED
        , cast(null as varchar) as CUMULATIVE_BONUS_AMOUNT_ON_HEAD
        , cast(null as varchar) as SUM_INSURED_FOR_HEAD
        , 'BJAZ_HM_GPA_BILL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_gpa_bill_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as HEAD_BASIS_DESCRIPTION
        , cast(null as varchar) as HEAD_ONSET_DATE
        , cast(null as varchar) as HEAD_RESOLUTION_DATE
        , cast(null as varchar) as HEAD_CLAIMED_PERIOD_FROM_DATE
        , cast(null as varchar) as HEAD_CLAIMED_PERIOD_TO_DATE
        , cast(null as varchar) as HEAD_ASSESSED_DURATION_DAYS
        , cast(null as varchar) as HEAD_CLAIMED_DURATION_DAYS
        , cast(null as varchar) as HEAD_BASIS_COUNT
        , cast(null as varchar) as HEAD_EVENT_DATE
        , cast(null as varchar) as TRAVEL_FROM_CITY
        , cast(null as varchar) as TRAVEL_TO_CITY
        , BSI as HEAD_BASE_SUM_INSURED
        , CUM_BONUS as CUMULATIVE_BONUS_AMOUNT_ON_HEAD
        , SUM_INSURED as SUM_INSURED_FOR_HEAD
        , 'BJAZ_HM_HCS_TECH_ASSESS_COV' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_BASIS_DESCRIPTION end) as HEAD_BASIS_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_ONSET_DATE end) as HEAD_ONSET_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_RESOLUTION_DATE end) as HEAD_RESOLUTION_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_CLAIMED_PERIOD_FROM_DATE end) as HEAD_CLAIMED_PERIOD_FROM_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_CLAIMED_PERIOD_TO_DATE end) as HEAD_CLAIMED_PERIOD_TO_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_ASSESSED_DURATION_DAYS end) as HEAD_ASSESSED_DURATION_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_CLAIMED_DURATION_DAYS end) as HEAD_CLAIMED_DURATION_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_BASIS_COUNT end) as HEAD_BASIS_COUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_EVENT_DATE end) as HEAD_EVENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRAVEL_FROM_CITY end) as TRAVEL_FROM_CITY,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRAVEL_TO_CITY end) as TRAVEL_TO_CITY,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEAD_BASE_SUM_INSURED end) as HEAD_BASE_SUM_INSURED,
        max(case when SOURCE_RUN = 'opus_health_v2' then CUMULATIVE_BONUS_AMOUNT_ON_HEAD end) as CUMULATIVE_BONUS_AMOUNT_ON_HEAD,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUM_INSURED_FOR_HEAD end) as SUM_INSURED_FOR_HEAD,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when HEAD_BASIS_DESCRIPTION is not null or HEAD_ONSET_DATE is not null or HEAD_RESOLUTION_DATE is not null or HEAD_CLAIMED_PERIOD_FROM_DATE is not null or HEAD_CLAIMED_PERIOD_TO_DATE is not null or HEAD_ASSESSED_DURATION_DAYS is not null or HEAD_CLAIMED_DURATION_DAYS is not null or HEAD_BASIS_COUNT is not null or HEAD_EVENT_DATE is not null or TRAVEL_FROM_CITY is not null or TRAVEL_TO_CITY is not null or HEAD_BASE_SUM_INSURED is not null or CUMULATIVE_BONUS_AMOUNT_ON_HEAD is not null or SUM_INSURED_FOR_HEAD is not null
                     then md5(upper(coalesce(cast(HEAD_BASIS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(HEAD_ONSET_DATE as varchar), '') || '|' || coalesce(cast(HEAD_RESOLUTION_DATE as varchar), '') || '|' || coalesce(cast(HEAD_CLAIMED_PERIOD_FROM_DATE as varchar), '') || '|' || coalesce(cast(HEAD_CLAIMED_PERIOD_TO_DATE as varchar), '') || '|' || coalesce(cast(HEAD_ASSESSED_DURATION_DAYS as varchar), '') || '|' || coalesce(cast(HEAD_CLAIMED_DURATION_DAYS as varchar), '') || '|' || coalesce(cast(HEAD_BASIS_COUNT as varchar), '') || '|' || coalesce(cast(HEAD_EVENT_DATE as varchar), '') || '|' || coalesce(cast(TRAVEL_FROM_CITY as varchar), '') || '|' || coalesce(cast(TRAVEL_TO_CITY as varchar), '') || '|' || coalesce(cast(HEAD_BASE_SUM_INSURED as varchar), '') || '|' || coalesce(cast(CUMULATIVE_BONUS_AMOUNT_ON_HEAD as varchar), '') || '|' || coalesce(cast(SUM_INSURED_FOR_HEAD as varchar), '')))
                end as SAT_CLAIM_BENEFIT_HEAD_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_BENEFIT_HEAD_HASHDIFF is not null
